import zipfile
import json
import os
import re
import shutil
from xml.etree import ElementTree as ET

# Paths
TEMPLATE = '/root/event_announcement_template.hwpx'
OUTPUT = '/root/event_announcement_ready.hwpx'
DATA_FILE = '/root/event_data.json'
EXTRACT_DIR = '/tmp/hwpx_work/extracted'

# Load JSON data
with open(DATA_FILE, 'r', encoding='utf-8') as f:
    data = json.load(f)

# Clean and extract template
if os.path.exists(EXTRACT_DIR):
    shutil.rmtree(EXTRACT_DIR)
os.makedirs(EXTRACT_DIR)

with zipfile.ZipFile(TEMPLATE, 'r') as zin:
    member_list = zin.namelist()
    zin.extractall(EXTRACT_DIR)

print(f"Loaded {len(data)} key-value pairs from JSON")
print(f"Extracted {len(member_list)} members from HWPX")

# Process each XML file
for root_dir, dirs, files in os.walk(EXTRACT_DIR):
    for fname in files:
        if not fname.endswith('.xml'):
            continue

        fpath = os.path.join(root_dir, fname)

        with open(fpath, 'r', encoding='utf-8') as f:
            content = f.read()

        # Skip files without placeholders
        if '{{' not in content and '}}' not in content:
            continue

        print(f"Processing: {fpath}")

        # Parse XML
        tree = ET.parse(fpath)
        root = tree.getroot()

        # Register namespace
        ns = {'hp': 'http://www.hancom.co.kr/hwpml/2010/HWPML'}

        # Find all elements with text content
        modified = False

        # Find all <hp:t> text elements
        for elem in root.iter():
            if elem.text and ('{{' in elem.text or '}}' in elem.text):
                old_text = elem.text

                # Replace placeholders
                def replacer(m):
                    key = m.group(1).strip()
                    if key in data:
                        return str(data[key])
                    else:
                        print(f"  Warning: Key '{key}' not found in data, keeping original")
                        return m.group(0)

                new_text = re.sub(r'\{\{\s*(.+?)\s*\}\}', replacer, old_text)
                elem.text = new_text
                modified = True

                if old_text != new_text:
                    print(f"  Replaced: '{old_text[:50]}...' -> '{new_text[:50]}...'")

        # Remove all linesegarray elements to prevent layout issues
        for elem in list(root.iter()):
            tag = elem.tag.split('}')[-1] if '}' in elem.tag else elem.tag
            if 'lineseg' in tag.lower():
                parent = None
                for parent_elem in root.iter():
                    for child in list(parent_elem):
                        if child is elem:
                            parent = parent_elem
                            break
                    if parent:
                        break

                if parent is not None:
                    try:
                        parent.remove(elem)
                        modified = True
                    except:
                        pass

        # Also try second pass for linesegarray removal using tag name directly
        for parent in root.iter():
            to_remove = []
            for child in parent:
                tag = child.tag.split('}')[-1] if '}' in child.tag else child.tag
                if 'lineseg' in tag.lower():
                    to_remove.append(child)
            for child in to_remove:
                parent.remove(child)
                modified = True

        # Write back with proper encoding
        if modified:
            tree.write(fpath, encoding='utf-8', xml_declaration=True)
            print(f"  Saved modified file")

# Rebuild the HWPX ZIP
if os.path.exists(OUTPUT):
    os.remove(OUTPUT)

print(f"\nRebuilding HWPX to {OUTPUT}")

with zipfile.ZipFile(OUTPUT, 'w', zipfile.ZIP_DEFLATED) as zout:
    for member in member_list:
        full_path = os.path.join(EXTRACT_DIR, member)
        if os.path.isfile(full_path):
            zout.write(full_path, member, compress_type=zipfile.ZIP_DEFLATED)
        elif os.path.isdir(full_path):
            # Add directory entries
            zout.write(full_path, member, compress_type=zipfile.ZIP_STORED)

print("HWPX written to", OUTPUT)

# Verify
print("\nVerifying output file...")
with zipfile.ZipFile(OUTPUT, 'r') as zf:
    for name in zf.namelist():
        if name.endswith('.xml'):
            content = zf.read(name).decode('utf-8', errors='replace')
            if '{{' in content or '}}' in content:
                print(f"  FAIL: Placeholder remaining in {name}")
                # Show remaining placeholders
                for m in re.finditer(r'.{0,40}\{\{.+?\}\}.{0,40}', content):
                    print(f"    Found: {m.group()}")
            else:
                print(f"  OK: No placeholders in {name}")

print("\nDone!")

